curl --request POST "${MODEMBOX_URL:-http://localhost:8000}/v1/hooks/rules" \
  --header "Authorization: Bearer ${MODEMBOX_TOKEN}" \
  --header 'Content-Type: application/json' \
  --data '{
  "name": "Forward incoming SMS",
  "enabled": false,
  "trigger": "sms.received",
  "actions": [
    {
      "type": "sms",
      "recipient": "+12025550123"
    }
  ]
}'

curl --request PUT "${MODEMBOX_URL:-http://localhost:8000}/v1/hooks/rules/1" \
  --header "Authorization: Bearer ${MODEMBOX_TOKEN}" \
  --header 'Content-Type: application/json' \
  --data '{
  "name": "Forward incoming SMS",
  "enabled": false,
  "trigger": "sms.received",
  "actions": [
    {
      "type": "sms",
      "recipient": "+12025550123"
    }
  ]
}'

curl --request POST "${MODEMBOX_URL:-http://localhost:8000}/v1/hooks/preview" \
  --header "Authorization: Bearer ${MODEMBOX_TOKEN}" \
  --header 'Content-Type: application/json' \
  --data '{
  "rule": {
    "name": "Forward incoming SMS",
    "enabled": false,
    "trigger": "sms.received",
    "actions": [
      {
        "type": "sms",
        "recipient": "+12025550123"
      }
    ]
  },
  "messageId": 1
}'
